using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin
{
    [GrasshopperCollection("Bench", "Math")]
    public interface IMathPack : IBettaCollection
    {
        [GrasshopperMethod("Remap", "Remaps a number from a source range to a target range")]
        double Remap(
            [GrasshopperParameter("Value")] double value,
            [GrasshopperParameter("Source Min")] double sourceMin,
            [GrasshopperParameter("Source Max")] double sourceMax,
            [GrasshopperParameter("Target Min")] double targetMin,
            [GrasshopperParameter("Target Max")] double targetMax);

        [GrasshopperMethod("Clamp", "Limits a number to a range")]
        double Clamp(
            [GrasshopperParameter("Value")] double value,
            [GrasshopperParameter("Min")] double min,
            [GrasshopperParameter("Max")] double max);

        [GrasshopperMethod("Lerp", "Linearly interpolates between two numbers")]
        double Lerp(
            [GrasshopperParameter("A")] double a,
            [GrasshopperParameter("B")] double b,
            [GrasshopperParameter("T")] double t);
    }

    public class MathPack : IMathPack
    {
        public double Remap(double value, double sourceMin, double sourceMax, double targetMin, double targetMax)
        {
            double span = sourceMax - sourceMin;
            if (span == 0) return targetMin;
            return targetMin + (value - sourceMin) / span * (targetMax - targetMin);
        }

        public double Clamp(double value, double min, double max)
        {
            if (min > max) (min, max) = (max, min);
            return Math.Min(Math.Max(value, min), max);
        }

        public double Lerp(double a, double b, double t) => a + (b - a) * t;
    }

    [GrasshopperCollection("Bench", "Geometry")]
    public interface IGeometryPack : IBettaCollection
    {
        [GrasshopperMethod("Divide Curve Stats", "Divides a curve into equal-length segments")]
        (List<Point3d> Points, double Length) DivideCurveStats(
            [GrasshopperParameter("Curve")] Curve curve,
            [GrasshopperParameter("Count", DefaultValue = 10)] int count);
    }

    public class GeometryPack : IGeometryPack
    {
        public (List<Point3d> Points, double Length) DivideCurveStats(Curve curve, int count)
        {
            var points = new List<Point3d>();
            if (curve == null || count < 1) return (points, 0);

            double length = curve.GetLength();
            var parameters = curve.DivideByCount(count, true);
            if (parameters != null)
                points.AddRange(parameters.Select(curve.PointAt));
            return (points, length);
        }
    }

    [GrasshopperCollection("Bench", "Data")]
    public interface IDataPack : IBettaCollection
    {
        [GrasshopperMethod("Async Stats", "Mean and standard deviation of a list of numbers, computed in the background")]
        (double Mean, double StdDev) AsyncStats(
            [GrasshopperParameter("Values")] List<double> values);
    }

    public class DataPack : IDataPack
    {
        // Latest computation. Replaced (and the previous one cancelled) whenever the inputs change.
        private static readonly object Gate = new object();
        private static double[] _inputs;
        private static CancellationTokenSource _cts;
        private static Task<(double Mean, double StdDev)> _task;

        public (double Mean, double StdDev) AsyncStats(List<double> values)
        {
            double[] snapshot = values == null ? new double[0] : values.ToArray();

            lock (Gate)
            {
                if (_inputs == null || !_inputs.SequenceEqual(snapshot))
                {
                    _cts?.Cancel();
                    _cts?.Dispose();
                    _cts = new CancellationTokenSource();
                    _inputs = snapshot;
                    _task = Task.Run(() => Compute(snapshot, _cts.Token), _cts.Token);
                }

                // Never block the UI: report the result once the background task has finished.
                if (_task.Status == TaskStatus.RanToCompletion) return _task.Result;
                return (double.NaN, double.NaN);
            }
        }

        private static (double Mean, double StdDev) Compute(double[] data, CancellationToken token)
        {
            if (data.Length == 0) return (0, 0);

            double sum = 0;
            foreach (var v in data) { token.ThrowIfCancellationRequested(); sum += v; }
            double mean = sum / data.Length;

            double sq = 0;
            foreach (var v in data) { token.ThrowIfCancellationRequested(); sq += (v - mean) * (v - mean); }
            return (mean, Math.Sqrt(sq / data.Length));
        }
    }
}
